<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Accessor\ThemeIsDefaultAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ThemeIsDefaultAccessor trait.
 *
 * Covers null default, string/VO assignment via withIsDefault,
 * getIsDefault/isDefault accessors, and isIsDefaultChanged with/without original.
 */
class ThemeIsDefaultAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withIsDefault creates a new instance with the IsDefault set
     * from a string value, and getIsDefault returns the primitive string.
     */
    public function testWithIsDefaultFromString(): void
    {
        // Arrange
        $holder = new ImplWithThemeIsDefaultAccessorUnitTest();

        // Act
        $result = $holder->withIsDefault(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isIsDefault());
    }
    /**
     * Asserts that withisDefault has access to the value object
     * from a string value, and getIsDefault returns the primitive string.
     */
    public function testWithIsDefaultFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithThemeIsDefaultAccessorUnitTest();

        // Act
        $result = $holder->withIsDefault(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isDefault()->value());
    }
    public function testChangedIsDefault(): void
    {
        // Arrange
        $holder = new ImplWithThemeIsDefaultAccessorUnitTest();
        $original = $holder->withIsDefault(true);
        $same = $holder->withIsDefault(true);
        $modified = $holder->withIsDefault(false);

        // Act
        $unchanged = $holder->isIsDefaultChanged();
        $withSame = $original->isIsDefaultChanged($same);
        $withDiferent = $original->isIsDefaultChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithThemeIsDefaultAccessorUnitTest
{
    use ThemeIsDefaultAccessor;
}
